data = []
for idx, item in enumerate(laptops_raw, start=1):
    name, brand, series, cpu, cpu_tag, gen, ram, storage, display, gpu, gpu_type, category, badge, badge_type, price, price_usd, img, use_cases = item
    
    brand_names = {
        'lenovo': 'Lenovo',
        'dell': 'Dell',
        'hp': 'HP',
        'apple': 'Apple',
        'microsoft': 'Microsoft'
    }
    
    obj = {
        "id": idx,
        "name": name,
        "brand": brand,
        "brandName": brand_names.get(brand, brand.capitalize()),
        "series": series,
        "cpu": cpu,
        "cpuTag": cpu_tag,
        "gen": gen,
        "ram": ram,
        "storage": storage,
        "display": display,
        "gpu": gpu,
        "gpuType": gpu_type,
        "category": category,
        "badge": badge,
        "badgeType": badge_type,
        "price": price,
        "priceFormatted": f"Rs {price:,}",
        "priceUsd": price_usd,
        "img": img,
        "condition": "Like New (10/10) · Certified Refurbished" if price < 250000 else "Open Box / Brand New Condition",
        "warranty": "1 Year Local Warranty + 7 Days Checking",
        "useCases": use_cases
    }
    data.append(obj)

js_content = f"// Complete 69-Laptop Real Inventory Dataset\nconst LAPTOPS_INVENTORY = {json.dumps(data, indent=2)};\n\nif (typeof module !== 'undefined') module.exports = LAPTOPS_INVENTORY;\n"

